import java.util.*;
import java.io.*;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String str = sc.nextLine();
        char[] inp = str.toCharArray();
        int n = str.length();

        String[] validEndings = {"00", "25", "50", "75"};
        long count = 0;

        for (String ending : validEndings) {
            boolean possible = true;
            int fixedX = -1;

            // Check last two digits
            for (int i = 0; i < 2; i++) {
                char curr = inp[n - 2 + i];
                char target = ending.charAt(i);

                if (curr == '_') {
                    continue;
                } else if (curr == 'X') {
                    if (fixedX == -1) {
                        fixedX = target - '0';
                    } else if (fixedX != target - '0') {
                        possible = false;
                        break;
                    }
                } else {
                    if (curr != target) {
                        possible = false;
                        break;
                    }
                }
            }

            if (!possible) continue;

            // Check consistency of X across the entire string
            if (fixedX != -1) {
                for (int i = 0; i < n; i++) {
                    if (inp[i] == 'X') {
                        if (i < n - 2) {
                            // For positions before last two, X can be any digit
                            continue;
                        }
                        // For last two positions, we already checked consistency
                    }
                }
            }

            // Count possibilities for the first n-2 digits
            long possibilities = 1;
            boolean hasLeadingX = false;
            boolean hasLeadingUnderscore = false;

            for (int i = 0; i < n - 2; i++) {
                if (inp[i] == '_') {
                    if (i == 0) {
                        possibilities *= 9; // Cannot be 0
                    } else {
                        possibilities *= 10;
                    }
                } else if (inp[i] == 'X') {
                    if (i == 0) {
                        hasLeadingX = true;
                    }
                }
            }

            // Handle X in the last two positions
            if (fixedX != -1) {
                // X is fixed, no additional choices
            } else {
                // Count X occurrences in first n-2 positions
                int xCount = 0;
                for (int i = 0; i < n - 2; i++) {
                    if (inp[i] == 'X') xCount++;
                }

                if (xCount > 0) {
                    if (hasLeadingX) {
                        possibilities *= 9; // X cannot be 0 if it's the first digit
                    } else {
                        possibilities *= 10; // X can be any digit
                    }
                }
            }

            // Check for leading zero in the final number
            if (n == 1) {
                if (inp[0] == '0' || inp[0] == '_' || (inp[0] == 'X' && fixedX == 0)) {
                    // Valid single zero
                } else if (inp[0] == 'X' && fixedX != 0 && fixedX != -1) {
                    continue; // X is fixed to non-zero, but we need to check if it's valid
                } else if (inp[0] != '0' && inp[0] != '_' && inp[0] != 'X') {
                    // It's a fixed non-zero digit
                } else if (inp[0] == 'X' && fixedX == -1) {
                    // X can be 0, but we need to handle it
                    if (ending.equals("00")) {
                        possibilities = 1; // Only one possibility: X=0
                    } else {
                        continue;
                    }
                }
            } else {
                // For numbers with more than one digit
                if (inp[0] == '0') {
                    continue; // Leading zero not allowed
                } else if (inp[0] == 'X') {
                    if (fixedX == 0) {
                        continue; // Leading zero not allowed
                    }
                    // If X is not fixed yet, we need to ensure it's not 0
                    if (fixedX == -1) {
                        // X will be determined, but if it's in the first position, it can't be 0
                        // This is already handled above
                    }
                }
            }

            // Special case: if the number is "00" or similar with leading zeros
            if (n == 2 && ending.equals("00")) {
                // "00" is not valid as it represents 0, but with two digits it has leading zero
                // However, the problem states that 0 (single digit) is valid, but 00 has leading zeros
                // So "00" should not be counted
                continue;
            }

            count += possibilities;
        }

        System.out.println(count);
    }
}
